)

type startEvent struct {
	id string
	at time.Duration
}

type timelineRuntime struct {
	mu        sync.Mutex
	active    int
	max       int
	log       []startEvent
	first     chan struct{}
	firstOnce sync.Once
	origin    time.Time
}

func (r *timelineRuntime) StartRun(_ context.Context, req runtimepkg.Request) (runtimepkg.Result, error) {
	r.mu.Lock()
	r.active++
	if r.active > r.max {
		r.max = r.active
	}
	id := req.Metadata["task.kind"] + ":" + req.Metadata["source.name"]
	r.log = append(r.log, startEvent{id: id, at: time.Since(r.origin)})
	first := len(r.log) == 1
	r.mu.Unlock()
	if first {
		r.firstOnce.Do(func() { close(r.first) })
	}
	time.Sleep(40 * time.Millisecond)
	path := req.Validation.Expectations[0].Path
	content := validSourceReport
	if req.Metadata["task.kind"] == string(TaskKindSynthesis) {
		content = validFinalReport
	}
	if err := osMkdirAllWrite(path, content); err != nil {
		return runtimepkg.Result{}, err
	}
	r.mu.Lock()
	r.active--
	r.mu.Unlock()
	return runtimepkg.Result{RunID: "probe", Status: "completed"}, nil
}

func (r *timelineRuntime) maxSnapshot() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.max
}

func osMkdirAllWrite(path, content string) error {
	if err := mkdirAll(filepath.Dir(path)); err != nil {
		return err
	}
	return writeFileBytes(path, content)
}

